import json, glob, re
cre = re.compile(r'permission|denied|\.\./|/etc/|/proc/|/root|traversal|outside|manifest|generator|expected_topology|task package|task.?side|benchmark', re.I)
for path in sorted(glob.glob('/workspace/traces/*/*.json')):
