    for i, m in enumerate(d['messages']):
        role = m.get('role')
        if role == 'system': continue
        texts = []
        c = m.get('content')
        if isinstance(c, str): texts.append(c)
        for tc in (m.get('tool_calls') or []):
            fn = tc.get('function', {})
            a = fn.get('arguments','')
            texts.append(str(a))
        t = ' '.join(texts)
        for mt in cre.finditer(t):
            s = max(0, mt.start()-90); e = min(len(t), mt.end()+90)
            print(f'{path.split(\"/\")[-2]}/{path.split(\"/\")[-1]} [{i}] {role} ({mt.group(0)}): ...{t[s:e].strip()[:200]}...')
            break
