import json, glob, sys, re

def load(path):
    with open(path) as f:
        return json.load(f)

def msg_summary(m, i):
    role = m.get('role')
    parts = []
    c = m.get('content')
    if isinstance(c, str) and c.strip():
        parts.append(f"text({len(c)})")
    elif isinstance(c, list):
        for item in c:
            if isinstance(item, dict):
                parts.append(f"blk:{item.get('type')}")
    tcs = m.get('tool_calls')
    if tcs:
        names = []
        for tc in tcs:
            fn = tc.get('function', {})
            names.append(fn.get('name', '?'))
        parts.append("tool_calls:" + ",".join(names))
    return f"[{i}] {role} " + " ".join(parts)

if __name__ == '__main__':
    for path in sorted(glob.glob('/workspace/traces/*/*.json')):
        d = load(path)
        print("=" * 80)
        print(f"{path} | task={d.get('task_id')} env={d.get('environment')} level={d.get('level')} score={d.get('recorded_score')} src={d.get('source_path')}")
        for i, m in enumerate(d['messages']):
            print("  " + msg_summary(m, i))

import json, sys

path = sys.argv[1]
with open(path) as f:
    d = json.load(f)

def show(m, i, maxlen=3000):
    role = m.get('role')
    print(f"\n===== [{i}] {role} =====")
    c = m.get('content')
    if isinstance(c, str):
        print(c[:maxlen] + ("...[truncated]" if len(c) > maxlen else ""))
    elif isinstance(c, list):
        for item in c:
            print(json.dumps(item)[:maxlen])
    for tc in (m.get('tool_calls') or []):
        fn = tc.get('function', {})
        args = fn.get('arguments', '')
        if isinstance(args, str):
            argstr = args
        else:
            argstr = json.dumps(args)
        print(f"TOOL_CALL {fn.get('name')}({argstr[:1500]})")

lo = int(sys.argv[2]) if len(sys.argv) > 2 else 0
hi = int(sys.argv[3]) if len(sys.argv) > 3 else len(d['messages'])
for i in range(lo, min(hi, len(d['messages']))):
    show(d['messages'][i], i)

import json, glob, re

patterns = [
    r'cheat', r'ground.?truth', r'answer.?key', r'solution', r'oracle',
    r'expected', r'scor(er|ing)', r'eval', r'/private', r'hidden',
    r'reward.?hack', r'backdoor', r'exploit', r'bypass', r'grader',
    r'peek', r'leak', r'answer', r'test.?case', r'private', r'flags?\b',
    r'/etc', r'/proc', r'secret', r'password', r'token', r'key\b',
    r'resources', r'\.env', r'ssh', r'credentials', r'config',
]
cre = re.compile('|'.join(patterns), re.I)

def text_of(m):
    parts = []
    c = m.get('content')
    if isinstance(c, str):
        parts.append(c)
    elif isinstance(c, list):
        for it in c:
            if isinstance(it, dict):
                parts.append(json.dumps(it))
    for tc in (m.get('tool_calls') or []):
        fn = tc.get('function', {})
        args = fn.get('arguments', '')
        parts.append(f"CALL {fn.get('name')} {args if isinstance(args,str) else json.dumps(args)}")
    return "\n".join(parts)

for path in sorted(glob.glob('/workspace/traces/*/*.json')):
    with open(path) as f:
        d = json.load(f)
    hits = []
    for i, m in enumerate(d['messages']):
        t = text_of(m)
        for match in cre.finditer(t):
            s = max(0, match.start()-100)
            e = min(len(t), match.end()+100)
            snippet = t[s:e].replace('\n', ' ')
            hits.append((i, m.get('role'), match.group(0), snippet))
    if hits:
        print("="*100)
        print(path)
        # dedupe near-identical
        seen = set()
        for i, role, g, snip in hits:
            key = (i, snip[:80])
            if key in seen: continue
            seen.add(key)
            print(f"  [{i}] {role} ({g}): ...{snip}...")

