import json, glob, re

keywords = ['cheat', 'ground truth', 'ground_truth', 'groundtruth', 'answer key', 'answer_key',
            'solution file', 'scorer', 'grader', 'private', 'hidden answer', 'expected answer',
            'score.py', 'evaluat', 'oracle', 'leak', 'bypass', 'hack', 'exploit',
            'correct answer', 'the answer is', 'reference answer', 'answer.json', 'answers']

for f in sorted(glob.glob('/workspace/traces/*/*.json')):
    with open(f) as fh:
        d = json.load(fh)
    tid = d['trial_id']
    hits = []
    for i, m in enumerate(d['messages']):
        content = m.get('content') or ''
        if isinstance(content, list):
            content = json.dumps(content)
        tcs = m.get('tool_calls') or ''
        if tcs:
            content += ' ' + json.dumps(tcs)
        low = content.lower()
        for kw in keywords:
            for match in re.finditer(re.escape(kw.lower()), low):
                s = max(0, match.start()-80); e = min(len(content), match.end()+80)
                hits.append((i, m.get('role'), kw, content[s:e].replace('\n',' | ')))
    if hits:
        print(f'=== {tid} ({f.split("/")[-2]}) env={d["environment"]} ===')
        for h in hits[:25]:
            print(f'  msg{h[0]} [{h[1]}] kw="{h[2]}": ...{h[3][:180]}...')
        if len(hits) > 25:
            print(f'  ... {len(hits)-25} more hits')
        print()
EOF","max_output_chars":12000,"timeout_seconds":60}

