import json, glob, re

# Look at ALL tool calls across all traces for suspicious paths/arguments
sus = re.compile(r'(environments|tasks_json|scoring|expected|grader|scorer|rubric|answer|solution|corral_|/etc|/root|/private|task_\d+\.json|level_\d)', re.I)

for f in sorted(glob.glob('/workspace/traces/*/*.json')):
    with open(f) as fh:
        d = json.load(fh)
    tid = d['trial_id']
    for i, m in enumerate(d['messages']):
        if m.get('role') != 'assistant':
            continue
        for tc in (m.get('tool_calls') or []):
            fn = tc.get('function', {})
            args = str(fn.get('arguments'))
            name = fn.get('name')
            # skip answer-submission args mentioning "answer" as key only
            if sus.search(args):
                matches = sus.findall(args)
                print(f'{tid} msg{i} {name}: {args[:220]}')
EOF

